<script setup lang="ts">
import { computed, ref, onMounted } from 'vue'
import { RefreshCw, Package } from 'lucide-vue-next'
import { can } from '../../app/access'
import { getBalances, getMovements, holdStock, type Balance, type Movement } from './api'
const balances = ref<Balance[]>([]); const movements = ref<Movement[]>([]); const loading = ref(true); const busy = ref(false); const notice = ref(''); const search = ref(''); const tab = ref('balances')
const selectedId = ref(''); const quantity = ref(1); const release = ref(false); const reason = ref('')
const filtered = computed(() => balances.value.filter(balance => `${balance.skuCode} ${balance.skuName} ${balance.ownerName}`.toLowerCase().includes(search.value.toLowerCase())))
async function load() { loading.value = true; try { [balances.value, movements.value] = await Promise.all([getBalances(), getMovements()]) } catch(e) { notice.value = e instanceof Error ? e.message : 'Không thể tải tồn kho' } finally { loading.value = false } }
async function save() { busy.value = true; notice.value = ''; try { await holdStock({ balance_id: selectedId.value, quantity: Number(quantity.value), release: release.value, reason: reason.value }); await load(); notice.value = 'Đã cập nhật trạng thái khóa hàng.'; reason.value = '' } catch(e) { notice.value = e instanceof Error ? e.message : 'Không thể cập nhật' } finally { busy.value = false } }
onMounted(load)
</script>
<template><div class="ops-page-heading"><div><h1>Tồn kho</h1><p>Tồn ghi sổ = khả dụng + giữ cho đơn + không khả dụng khác.</p></div><button class="ops-button secondary" :disabled="loading || busy" @click="load"><RefreshCw :size="15"/> Làm mới</button></div><p v-if="notice" class="ops-alert" role="status">{{ notice }}</p><div class="module-tabs"><button :class="{ active: tab === 'balances' }" @click="tab = 'balances'">Số dư tồn kho</button><button :class="{ active: tab === 'movements' }" @click="tab = 'movements'">Lịch sử nhập / xuất</button></div><p v-if="loading" class="ops-loading">Đang tải tồn kho…</p><template v-else><section v-if="tab === 'balances'" class="ops-panel"><div class="ops-panel-heading"><h2><Package :size="17"/> {{ balances.length }} dòng tồn theo chủ hàng / SKU / vị trí</h2><input v-model="search" class="ops-compact-input" aria-label="Tìm tồn kho" placeholder="Tìm SKU, chủ hàng…"/></div><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>SKU / tên hàng</th><th>Chủ hàng</th><th>Vị trí</th><th>Đơn vị</th><th>Tồn ghi sổ</th><th>Khả dụng</th><th>Đã giữ</th><th>Không khả dụng</th><th v-if="can('inventory.manage')">Thao tác</th></tr></thead><tbody><tr v-for="b in filtered" :key="b.id"><td>{{ b.skuCode }}<small class="module-cell-note">{{ b.skuName }}</small></td><td>{{ b.ownerName }}</td><td>{{ b.locationCode }}</td><td>{{ b.unit }}</td><td>{{ b.onHand }}</td><td>{{ b.available }}</td><td>{{ b.reserved }}</td><td>{{ b.unavailable }}</td><td v-if="can('inventory.manage')"><button class="module-code-button" @click="selectedId = b.id">Khóa / mở khóa</button></td></tr><tr v-if="!filtered.length"><td colspan="9" class="ops-empty">Chưa có tồn kho phù hợp.</td></tr></tbody></table></div></section><section v-else class="ops-panel"><div class="ops-panel-heading"><h2>Giao dịch đã ghi nhận</h2></div><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>Thời gian</th><th>Loại</th><th>SKU</th><th>Chủ hàng</th><th>Số lượng</th></tr></thead><tbody><tr v-for="m in movements" :key="m.id"><td>{{ new Date(m.at).toLocaleString('vi-VN') }}</td><td>{{ m.kind === 'INBOUND' ? 'Nhập kho' : 'Xuất bàn giao' }}</td><td>{{ m.skuCode }}</td><td>{{ balances.find(b => b.ownerId === m.ownerId)?.ownerName ?? m.ownerId }}</td><td>{{ m.kind === 'INBOUND' ? '+' : '-' }}{{ m.quantity }}</td></tr><tr v-if="!movements.length"><td colspan="5" class="ops-empty">Chưa có giao dịch nhập/xuất được ghi nhận.</td></tr></tbody></table></div></section>
<form v-if="selectedId && can('inventory.manage')" class="ops-panel module-form module-detail" @submit.prevent="save"><h2>Khóa / mở khóa hàng · {{ balances.find(b => b.id === selectedId)?.skuCode }}</h2><div class="module-fields"><label>Thao tác<select v-model="release"><option :value="false">Khóa lượng khả dụng</option><option :value="true">Mở khóa lượng không khả dụng</option></select></label><label>Số lượng<input v-model.number="quantity" type="number" min="1" required/></label><label>Lý do<input v-model="reason" minlength="3" maxlength="500" required/></label></div><p class="module-note">Không khóa chồng lên lượng đã giữ cho đơn xuất.</p><div class="ops-actions"><button class="ops-button" :disabled="busy">Lưu thay đổi</button><button class="ops-button secondary" type="button" @click="selectedId = ''">Đóng</button></div></form></template></template>
